contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    // to - address passed to multiplicate
    // sendAmt - wei forwarded to multiplicate
    function run(address to, uint256 sendAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmt)); require(sendAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmt);

        // observe Owner before and contract balance (balance read-only)
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;

        // call multiplicate and record whether it reverted
        bool reverted;
        c.multiplicate{value: sendAmt}(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe Owner after and balance after
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        // General invariant: Owner never changes because no function in C updates Owner.
        // Assert that Owner stays equal before and after the call (regardless of revert or ether movement).
        assert(ownerBefore == ownerAfter);
    }

    receive() external payable {}
}

