pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(address to, uint256 sendAmt) internal {
        sendAmt = bound(sendAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmt);
        address ownerBefore;
        try c.Owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.multiplicate{value: sendAmt}(to) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter;
        try c.Owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        uint256 balAfter = address(c).balance;
        assertTrue(ownerBefore == ownerAfter);
    }

    function testFuzz_run(address to, uint256 sendAmt) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, sendAmt);
    }

    receive() external payable {}
}
